import Browserbase from "@browserbasehq/sdk";

const bb = new Browserbase({
  apiKey: process.env.BROWSERBASE_API_KEY,
});

const { data: policies } = await bb.navigationPolicies.list();

for (const policy of policies) {
  console.log(policy.id, policy.name);
}

import Browserbase from "@browserbasehq/sdk";

const bb = new Browserbase({
  apiKey: process.env.BROWSERBASE_API_KEY,
});

const policy = await bb.navigationPolicies.create({
  name: "Research agents",
  defaultDecision: "allow",
  blockedCategories: ["gambling", "adult", "malware"],
  domainOverrides: [
    { domain: "internal.example.com", decision: "block" },
  ],
});

console.log(policy.id);

curl --request POST \
  --url https://api.browserbase.com/v1/navigation-policies \
  --header 'Content-Type: application/json' \
  --header "X-BB-API-Key: $BROWSERBASE_API_KEY" \
  --data '{
    "name": "Research agents",
    "defaultDecision": "allow",
    "blockedCategories": ["gambling", "adult", "malware"],
    "domainOverrides": [
      { "domain": "internal.example.com", "decision": "block" }
    ]
  }'

import Browserbase from "@browserbasehq/sdk";

const bb = new Browserbase({
  apiKey: process.env.BROWSERBASE_API_KEY,
});

await bb.navigationPolicies.delete("<policy-id>");

import Browserbase from "@browserbasehq/sdk";

const bb = new Browserbase({
  apiKey: process.env.BROWSERBASE_API_KEY,
});

const policy = await bb.navigationPolicies.retrieve("<policy-id>");

console.log(policy.domainOverrides);

import Browserbase from "@browserbasehq/sdk";

const bb = new Browserbase({
  apiKey: process.env.BROWSERBASE_API_KEY,
});

const policy = await bb.navigationPolicies.update("<policy-id>", {
  domainOverrides: [
    { domain: "internal.example.com", decision: "block" },
    { domain: "partner.example.net", decision: "allow" },
  ],
});

console.log(policy.domainOverrides);

