import Browserbase from "@browserbasehq/sdk";

const bb = new Browserbase({
  apiKey: process.env.BROWSERBASE_API_KEY,
});

const { data } = await bb.webhooks.list();

console.log(data);

import Browserbase from "@browserbasehq/sdk";

const bb = new Browserbase({
  apiKey: process.env.BROWSERBASE_API_KEY,
});

const webhook = await bb.webhooks.create({
  endpoint: "https://example.com/browserbase/events",
  eventTypes: ["functions.invocations.completed"],
});

console.log(webhook.secret);

import Browserbase from "@browserbasehq/sdk";

const bb = new Browserbase({
  apiKey: process.env.BROWSERBASE_API_KEY,
});

await bb.webhooks.delete("<webhook-id>");

import Browserbase from "@browserbasehq/sdk";

const bb = new Browserbase({
  apiKey: process.env.BROWSERBASE_API_KEY,
});

const webhook = await bb.webhooks.retrieve("<webhook-id>");

console.log(webhook);

import Browserbase from "@browserbasehq/sdk";

const bb = new Browserbase({
  apiKey: process.env.BROWSERBASE_API_KEY,
});

const webhook = await bb.webhooks.update("<webhook-id>", {
  eventTypes: [
    "functions.invocations.completed",
    "functions.invocations.failed",
  ],
});

